{
  "status": "blocked",
  "message": "I can’t close your EcoCard yet because a replacement card is currently shipped and has not been delivered.",
  "replacement_order": {
    "order_date": "11/08/2025",
    "expected_delivery": "11/18/2025",
    "status": "SHIPPED"
  },
  "next_steps": "The replacement card must be delivered or the order must be cancelled before the EcoCard can be closed. Your EcoCard remains open."
}

{
  "status": "still_blocked",
  "message": "I understand. I checked the replacement order again, but Rho-Bank’s system still shows it as SHIPPED rather than DELIVERED. Because the order status is not final, I’m unable to close the EcoCard at this time.",
  "order_details": {
    "order_date": "11/08/2025",
    "expected_delivery": "11/18/2025",
    "current_status": "SHIPPED"
  },
  "next_step": "Would you like me to transfer this status discrepancy to a human specialist?"
}

{
  "status": "blocked",
  "message": "I can’t close your Gold Rewards Card yet because it has an outstanding balance of $175.00. The balance must be paid in full and reach $0.00 before closure.",
  "checks": {
    "pending_replacement_card": "None found",
    "account_age": "Eligible based on the account opening date of 05/20/2024",
    "outstanding_balance": "$175.00"
  },
  "next_step": "After the balance is fully paid and posted, you can request closure of the Gold Rewards Card."
}

{
  "status": "unable_to_process",
  "message": "I couldn’t pay off the Gold Rewards Card because your Rho-Bank checking account has $50.00 available, while the card balance is $175.00.",
  "amounts": {
    "gold_rewards_card_balance": "$175.00",
    "checking_account_balance": "$50.00",
    "shortfall": "$125.00"
  },
  "next_step": "Please deposit or transfer at least $125.00 into the checking account. Once the funds are available, the full $175.00 payment can be processed."
}

{
  "status": "not_reflected",
  "message": "I checked again, but the payment has not posted to your Rho-Bank accounts.",
  "current_balances": {
    "checking_account": "$50.00",
    "gold_rewards_card": "$175.00"
  },
  "next_step": "The Gold Rewards Card remains unpaid. Please confirm that the transfer was sent to the correct Rho-Bank checking account and allow it to post before requesting closure."
}

{
  "status": "retention_option",
  "message": "I’ve recorded annual-fee concerns for your Crypto-Cash Back card. Since the account is less than two years old, I can offer a permanent downgrade to the no-annual-fee Bronze Rewards Card.",
  "downgrade_details": {
    "target_card": "Bronze Rewards Card",
    "annual_fee": "$0",
    "preserved": [
      "Account history",
      "Credit line",
      "Unredeemed rewards at the same value"
    ],
    "changes": "Rewards rates and card benefits would change to those of the Bronze Rewards Card."
  },
  "question": "Would you like to downgrade instead, or do you want to continue with closing the Crypto-Cash Back card?"
}

{
  "status": "retention_offer",
  "message": "Understood. Before I close the Crypto-Cash Back card, I can offer one final retention option: either 500 bonus points or a $5 statement credit.",
  "question": "Would you like the 500 bonus points or the $5 statement credit, or would you like to decline both and proceed with closure?"
}

{
  "status": "offer_unchanged",
  "message": "I checked your Rho-Bank credit card accounts. There is no Platinum Rewards Card currently listed; your open cards are the EcoCard, Gold Rewards Card, and Crypto-Cash Back card. The Green Rewards Card is closed.",
  "explanation": "The retention offer is based on the tier of the card being closed. The Crypto-Cash Back card is entry-tier, so the applicable offer is 500 bonus points or a $5 statement credit—not the premium-card offer.",
  "next_step": "If you decline both applicable offers, I can proceed with closing the Crypto-Cash Back card. Please confirm that you want to decline them and close the account."
}
